using System.Buffers.Binary;
using System.Numerics;
using MautAssistent;

// Independent wire fixtures: offsets/build bytes are literal protocol facts,
// rather than copied from the encoder or generated by product serialization.
public static class SceneSnapshotAdversarialTests
{
    const long Now=1000000;
    const uint Pid=321;
    const int ScopeStart=32928;
    static void U32(byte[] b,int p,uint x)=>BinaryPrimitives.WriteUInt32LittleEndian(b.AsSpan(p),x);
    static void U64(byte[] b,int p,ulong x)=>BinaryPrimitives.WriteUInt64LittleEndian(b.AsSpan(p),x);
    static void I64(byte[] b,int p,long x)=>BinaryPrimitives.WriteInt64LittleEndian(b.AsSpan(p),x);
    static void F32(byte[] b,int p,float x)=>BinaryPrimitives.WriteSingleLittleEndian(b.AsSpan(p),x);
    static void D64(byte[] b,int p,double x)=>BinaryPrimitives.WriteDoubleLittleEndian(b.AsSpan(p),x);
    static byte[] Frame()
    {
        var b=new byte[41120];
        U32(b,0,0x3143534D);U32(b,4,1);U32(b,8,41120);U32(b,12,2);
        I64(b,16,Now);U32(b,24,Pid);U32(b,28,59);U64(b,32,1234);
        U64(b,40,2000000);U64(b,48,1900000);U64(b,144,1);U64(b,152,2000000);
        D64(b,96,double.PositiveInfinity);
        Convert.FromHexString("C65EFA730837A8C05FE382C330C2F4DFFEEEC69FBDA81BB0F89072C2C4ABA6D5").CopyTo(b,112);
        U32(b,88,1);U32(b,92,1);Scope(b,0,55,3);
        return b;
    }
    static void Scope(byte[] b,int index,ulong id,uint flags)
    {int p=ScopeStart+16*index;U64(b,p,id);U32(b,p+8,flags);}
    static void Body(byte[] b,int index,ulong id=10,ulong group=10,uint flags=0)
    {
        int p=160+64*index;U64(b,p,id);U32(b,p+8,flags);F32(b,p+16,20);F32(b,p+20,2);F32(b,p+24,10);
        F32(b,p+40,1);F32(b,p+44,1);F32(b,p+48,2);F32(b,p+52,6);U64(b,p+56,group);
    }
    static bool Reject(Action<byte[]> mutate)
    {var b=Frame();mutate(b);return SceneSnapshotProtocol.Decode(b,Now,Pid)==null;}
    public static void WireAuthority(Action<bool,string> assert)
    {
        var b=Frame();var snapshot=SceneSnapshotProtocol.Decode(b,Now,Pid);
        assert(snapshot!=null&&snapshot.Covers(55,Vector3.Zero,30,2000000,2000000),"A complete empty current parked scene is distinct from absent/default input");
        assert(SceneSnapshotProtocol.Decode(b.AsSpan(0,41119),Now,Pid)==null,"A truncated wire frame is rejected");
        foreach(var item in new (int Offset,uint Value)[]{(0,0),(4,2),(8,41119),(12,0),(12,3),(24,0),(24,322),(28,63),(28,58),(28,0),(104,1),(108,1)})
            assert(Reject(x=>U32(x,item.Offset,item.Value)),"Invalid wire header or incomplete/paused/unknown status cannot mean clear");
        assert(Reject(x=>x[112]^=1),"An unknown producer build cannot borrow the protocol version");
        assert(Reject(x=>U64(x,32,0))&&Reject(x=>U64(x,144,0)),"Missing source session/generation is rejected");
        assert(SceneSnapshotProtocol.Decode(b,Now+200,Pid)!=null&&SceneSnapshotProtocol.Decode(b,Now+201,Pid)==null,"UTC read freshness expires at the declared boundary");
        assert(SceneSnapshotProtocol.Decode(b,Now-25,Pid)!=null&&SceneSnapshotProtocol.Decode(b,Now-26,Pid)==null,"Future producer timestamps have a bounded tolerance");
        assert(Reject(x=>I64(x,16,long.MinValue)),"UTC arithmetic cannot overflow into fresh evidence");
        foreach(double value in new[]{double.NaN,double.PositiveInfinity,double.NegativeInfinity})assert(Reject(x=>D64(x,56,value)),"Invalid own coordinates are rejected");
        assert(!snapshot!.Covers(0,Vector3.Zero,30,2000000,2000000),"No requested UID cannot establish relevant scope");
        assert(!snapshot.Covers(56,Vector3.Zero,30,2000000,2000000),"An unrelated loaded prefab cannot authorize the wanted one");
        assert(!snapshot.Covers(55,new(.751f,0,0),30,2000000,2000000),"Source pose must agree with the current own rig");
        assert(!snapshot.Covers(55,Vector3.Zero,30,2250001,2000000)&&!snapshot.Covers(55,Vector3.Zero,30,2000000,2250001),"Simulation and render clocks are independently bound");
        foreach(double radius in new[]{double.NaN,double.PositiveInfinity,-1,1001})assert(!snapshot.Covers(55,Vector3.Zero,radius,2000000,2000000),"Invalid corridor extent cannot establish coverage");
    }
    public static void BodiesAndCounts(Action<bool,string> assert)
    {
        var b=Frame();U32(b,80,1);U32(b,84,1);Body(b,0);
        var s=SceneSnapshotProtocol.Decode(b,Now,Pid);
        assert(s!=null&&s.Bodies.Count==1&&s.Bodies[0].Center==new Vector3(20,2,10)&&s.Bodies[0].Rotation==Quaternion.Identity,"Actual XYZW/body offsets decode independently of producer structure packing");
        foreach(var bad in new (int Offset,uint Value)[]{(80,513),(88,513),(80,1),(88,2),(84,100001),(92,100001)})
            assert(Reject(x=>U32(x,bad.Offset,bad.Value)),"Invalid capacity/count relationships are rejected");
        bool BadBody(Action<byte[],int> mutate){var x=Frame();U32(x,80,1);U32(x,84,1);Body(x,0);mutate(x,160);return SceneSnapshotProtocol.Decode(x,Now,Pid)==null;}
        assert(BadBody((x,p)=>U64(x,p,0))&&BadBody((x,p)=>U64(x,p+56,0)),"Body identity and chain identity are both required");
        assert(BadBody((x,p)=>U32(x,p+8,4)),"Unknown body flags cannot be ignored");
        assert(BadBody((x,p)=>F32(x,p+12,1)),"A speed value cannot masquerade as measured motion without its evidence flag");
        assert(BadBody((x,p)=>{U32(x,p+8,2);F32(x,p+12,-10);}),"Producer speed is a nonnegative magnitude; a negative value cannot shrink motion reserves");
        foreach(float invalid in new[]{float.NaN,float.PositiveInfinity,-1,0,101})assert(BadBody((x,p)=>F32(x,p+44,invalid)),"Malformed physical half extents are rejected");
        assert(BadBody((x,p)=>F32(x,p+16,float.NaN))&&BadBody((x,p)=>F32(x,p+40,0)),"Invalid body pose cannot become a clear obstacle");
        b=Frame();U32(b,80,2);U32(b,84,2);Body(b,0);Body(b,1);
        assert(SceneSnapshotProtocol.Decode(b,Now,Pid)==null,"Duplicate source body IDs cannot silently hide a trailer");
        Body(b,1,11,10,1);s=SceneSnapshotProtocol.Decode(b,Now,Pid);
        assert(s?.Bodies.Count==2&&s.Bodies[1].GroupId==10&&(s.Bodies[1].Flags&1)!=0,"Distinct trailer and tractor bodies may share their chain group");
        foreach(double value in new[]{double.NaN,-1,double.NegativeInfinity,0})assert(Reject(x=>D64(x,96,value)),"A complete uncapped list must explicitly encode no omitted bodies");
    }
    public static void LocalScopeAndOverflow(Action<bool,string> assert)
    {
        var b=Frame();U32(b,88,2);U32(b,92,2);Scope(b,1,99,0);
        var s=SceneSnapshotProtocol.Decode(b,Now,Pid);
        assert(s!=null,"A known far prefab with unavailable segment does not erase the successfully enumerated local world");
        assert(s!.Covers(55,Vector3.Zero,30,2000000,2000000)&&!s.Covers(99,Vector3.Zero,30,2000000,2000000),"Segment evidence is required for the requested UID, not every unrelated prefab");
        Scope(b,1,99,1);s=SceneSnapshotProtocol.Decode(b,Now,Pid);
        assert(s!=null&&!s.Covers(99,Vector3.Zero,30,2000000,2000000),"Loaded without actors-enumerated is insufficient for the requested prefab");
        Scope(b,1,55,3);assert(SceneSnapshotProtocol.Decode(b,Now,Pid)==null,"Conflicting duplicate scope IDs cannot be folded into a loaded claim");
        b=Frame();U32(b,80,512);U32(b,84,513);
        for(int i=0;i<512;i++)Body(b,i,(ulong)i+1);
        D64(b,96,30);s=SceneSnapshotProtocol.Decode(b,Now,Pid);
        assert(s!=null&&!s.Covers(55,Vector3.Zero,30,2000000,2000000),"An omitted body touching the stopping corridor prevents coverage");
        D64(b,96,30.01);s=SceneSnapshotProtocol.Decode(b,Now,Pid);
        assert(s!=null&&s.Covers(55,Vector3.Zero,30,2000000,2000000),"Explicitly distant omitted surfaces permit a bounded local corridor");
        assert(!s!.Covers(55,new(.1f,0,0),30,2000000,2000000),"Own motion since capture consumes the omitted-distance margin");
        D64(b,96,double.PositiveInfinity);assert(SceneSnapshotProtocol.Decode(b,Now,Pid)==null,"A truncated producer cannot claim infinite omitted coverage");
    }
    public static void Progression(Action<bool,string> assert)
    {
        var start=SceneSnapshotProtocol.Decode(Frame(),Now,Pid)!;
        var timeline=new SceneTimeline();
        assert(timeline.Accept(start,Now),"The first coherent producer frame establishes a timeline");
        assert(timeline.Accept(start,Now+199),"Repeated reads retain only the original short producer lease");
        assert(!timeline.Accept(start,Now+201),"Rereading the same bytes never renews the producer timestamp");
        timeline.Reset();assert(timeline.Accept(start,Now),"An explicit reader reset can establish its new stream");
        var frozen=start with{Sequence=4,UtcMs=Now+150,RenderTime=start.RenderTime+150000,SimulationTime=start.SimulationTime+150000};
        assert(timeline.Accept(frozen,Now+150),"A brief physical tick gap is bounded rather than immediately classified as motion");
        assert(!timeline.Accept(frozen with{Sequence=6,UtcMs=Now+201},Now+201),"New source copies and rendering cannot indefinitely renew a frozen paused-simulation clock");
        foreach(var mutate in new Func<SceneSnapshot,SceneSnapshot>[]{
            x=>x with{Sequence=0},x=>x with{UtcMs=x.UtcMs-1},x=>x with{SimulationTime=x.SimulationTime-1},
            x=>x with{PausedSimulationTime=x.PausedSimulationTime-1},x=>x with{RenderTime=x.RenderTime-1},
            x=>x with{Generation=x.Generation-1}}) {
            timeline.Reset();timeline.Accept(start,Now);
            assert(!timeline.Accept(mutate(start),Now),"Clock, sequence, and generation rollback cannot replace previously accepted evidence");
        }
        timeline.Reset();timeline.Accept(start,Now);
        var advanced=start with{Sequence=4,UtcMs=Now+50,SimulationTime=2050000,PausedSimulationTime=1950000,RenderTime=2050000};
        assert(timeline.Accept(advanced,Now+50),"All source clocks progress in the same generation");
        assert(!timeline.Accept(start with{UtcMs=Now+51},Now+51),"A late callback cannot roll back an already observed newer frame");
        var reset=advanced with{Sequence=6,Generation=2,UtcMs=Now+60,SimulationTime=0,PausedSimulationTime=0,RenderTime=0};
        assert(timeline.Accept(reset,Now+60),"A new explicit source generation permits a timer restart");
        assert(!timeline.Accept(advanced with{Sequence=6,UtcMs=Now+61},Now+61),"The old pre-reset generation cannot resurrect after restart");
        assert(timeline.Accept(reset with{Sequence=8,UtcMs=Now+100,SimulationTime=40000,PausedSimulationTime=40000,RenderTime=40000},Now+100),"Post-reset clocks can establish current source progression");
        assert(!timeline.Accept(reset with{Sequence=10,UtcMs=Now+90,SimulationTime=50000,PausedSimulationTime=50000,RenderTime=50000},Now+110),"A source UTC rollback is not hidden by advancing simulation clocks");
    }
    public static void SourceResurrection(Action<bool,string> assert)
    {
        var original=SceneSnapshotProtocol.Decode(Frame(),Now,Pid)!;
        var timeline=new SceneTimeline();timeline.Accept(original,Now);
        assert(timeline.Accept(original,Now+1),"An identical short-leased source frame may be read again");
        foreach(var changed in new[]{
            original with{UtcMs=Now+1},original with{SimulationTime=original.SimulationTime+1},
            original with{PausedSimulationTime=original.PausedSimulationTime+1},original with{RenderTime=original.RenderTime+1},
            original with{OwnPosition=Vector3.UnitX*.1f},original with{BodyTotal=1,OmittedMinSurfaceDistance=20},
            original with{Scopes=new[]{new SceneScope(55,1)}},
            original with{Bodies=new[]{new SceneBody(9,0,0,Vector3.Zero,Quaternion.Identity,Vector3.One,9)},BodyTotal=1}}) {
            timeline.Reset();timeline.Accept(original,Now);
            assert(!timeline.Accept(changed,Now+1),"The same producer sequence cannot carry a different header or body/scope payload");
        }
        timeline.Reset();timeline.Accept(original,Now);
        var next=original with{Session=5678,Sequence=2,UtcMs=Now+10};
        assert(timeline.Accept(next,Now+10),"A new producer session can establish an explicit new stream");
        assert(!timeline.Accept(original with{Sequence=4,UtcMs=Now+11,PausedSimulationTime=1900011},Now+11),"An already retired source session cannot reappear through a late callback");
        timeline.Reset();assert(timeline.Accept(original,Now),"Explicit reader lifecycle reset clears retired identities for a genuinely new connection");
        assert(timeline.Accept(original with{Sequence=6,UtcMs=Now+10},Now+10),"A newer producer sequence is accepted within its valid time lease");
        assert(!timeline.Accept(original with{Generation=2,Sequence=4,UtcMs=Now+20,SimulationTime=0,PausedSimulationTime=0,RenderTime=0},Now+20),"A timer generation change cannot hide a producer sequence rollback");
        assert(timeline.Accept(original with{Generation=2,Sequence=8,UtcMs=Now+20,SimulationTime=0,PausedSimulationTime=0,RenderTime=0},Now+20),"Timer reset changes clock generation while preserving source publication order");
    }
    public static void Clearance(Action<bool,string> assert)
    {
        var road=new SceneCurve(new(0,0,0),new(0,0,10),new(0,0,20),new(0,0,30));
        var body=new SceneBody(1,2,0,new(0,2,15),Quaternion.Identity,new(1,2,3),1);
        assert(!SceneClearance.Outside(road,body,4.4f,3.4f),"A real body in the own-profile corridor is occupied");
        assert(SceneClearance.Outside(road,body with{Center=new(20,2,15)},4.4f,3.4f),"A separately measured far parked body is not a global model blocker");
        assert(!SceneClearance.Outside(road,body with{Center=new(0,2,15),Rotation=Quaternion.CreateFromAxisAngle(Vector3.UnitY,.7f)},4.4f,3.4f),"A rotated box crossing the route remains occupied");
        assert(SceneClearance.Outside(road,body with{Center=new(0,20,15)},4.4f,3.4f),"A physically separate upper body does not become a false road obstacle");
        assert(!SceneClearance.Outside(road,body with{Center=new(2.8f,2,15)},4.4f,3.4f),"A sub-reserve separation cannot become clear through point sampling");
        foreach(var invalid in new[]{body with{HalfExtents=Vector3.Zero},body with{Center=new(float.NaN,0,0)},body with{Rotation=default}})
            assert(!SceneClearance.Outside(road,invalid,4.4f,3.4f),"Malformed body geometry cannot produce a separation certificate");
        // Every control point individually lies far away; the Bezier itself
        // crosses the centre. A point-only/sparse endpoint check would miss it.
        var bow=new SceneCurve(new(-20,0,0),new(-20,0,30),new(20,0,0),new(20,0,30));
        assert(!SceneClearance.Outside(bow,body,4.4f,3.4f),"The entire cubic hull subdivision, rather than only control points, must be considered");
    }
    public static void CoupledRigBound(Action<bool,string> assert)
    {
        var truck=new VehicleBody(Vector3.Zero,Quaternion.Identity,new(-1,0,-2),new(1,3,3));
        var trailer=new VehicleBody(Vector3.Zero,Quaternion.Identity,new(-1,0,-8),new(1,3,2));
        var truckHook=new Vector3(0,1,2);var trailerHook=new Vector3(0,1,-7);
        var rng=new Random(81723);float? reference=null;
        for(int i=0;i<64;i++) {
            var tq=Quaternion.CreateFromYawPitchRoll((float)(rng.NextDouble()*6.2),(float)(rng.NextDouble()*1.2-.6),(float)(rng.NextDouble()*1.2-.6));
            var aq=Quaternion.CreateFromYawPitchRoll((float)(rng.NextDouble()*6.2),(float)(rng.NextDouble()*1.2-.6),(float)(rng.NextDouble()*1.2-.6));
            var t=truck with{Rotation=tq};var joint=t.Position+Vector3.Transform(truckHook,tq);
            var a=trailer with{Rotation=aq,Position=joint-Vector3.Transform(trailerHook,aq)};
            var rig=new VehicleGeometry(321,1,2,Now,t,true,a);
            float radius=RigReach.Radius(rig,truckHook,trailerHook);
            assert(float.IsFinite(radius)&&t.Corners().Concat(a.Corners()).All(p=>Vector3.Distance(p,t.Position)<radius),"A real hook-coupled rig remains enclosed across arbitrary yaw, pitch and roll");
            reference??=radius;assert(Math.Abs(radius-reference.Value)<.001,"The conservative local joint bound cannot shrink with a favorable current orientation");
        }
        var goodTrailer=trailer with{Position=truckHook-trailerHook};
        var good=new VehicleGeometry(321,1,2,Now,truck,true,goodTrailer);
        assert(float.IsNaN(RigReach.Radius(good,truckHook,null)),"Missing actual trailer coupling cannot become a low rig bound");
        assert(float.IsNaN(RigReach.Radius(good,truckHook,new(100,0,0))),"An implausible and physically unmatched coupling is rejected");
        assert(float.IsNaN(RigReach.Radius(good with{Trailer=goodTrailer with{Position=goodTrailer.Position+Vector3.UnitX}},truckHook,trailerHook)),"Independently observed world joints must actually agree");
        foreach(var invalid in new[]{
            good with{Truck=truck with{Position=new(float.NaN,0,0)}},
            good with{Truck=truck with{Rotation=default}},
            good with{Trailer=goodTrailer with{Rotation=default}},
            good with{TrailerKnown=false,Trailer=null}})
            assert(float.IsNaN(RigReach.Radius(invalid,truckHook,trailerHook)),"Malformed or unknown native pose cannot bypass joint agreement through NaN arithmetic");
        // A real SCS-local kingpin may lie beyond the visible native model.
        // The direct hook-to-corner triangle bound needs no inside-box premise.
        var externalTruckHook=new Vector3(0,1,4);var externalTrailerHook=new Vector3(0,1,-10);
        for(int i=0;i<64;i++) {
            var tq=Quaternion.CreateFromYawPitchRoll((float)(rng.NextDouble()*6.2),(float)(rng.NextDouble()*1.2-.6),(float)(rng.NextDouble()*1.2-.6));
            var aq=Quaternion.CreateFromYawPitchRoll((float)(rng.NextDouble()*6.2),(float)(rng.NextDouble()*1.2-.6),(float)(rng.NextDouble()*1.2-.6));
            var t=truck with{Rotation=tq};
            var joint=t.Position+Vector3.Transform(externalTruckHook,tq);
            var a=trailer with{Rotation=aq,Position=joint-Vector3.Transform(externalTrailerHook,aq)+Vector3.UnitY*.24f};
            float radius=RigReach.Radius(new(321,1,2,Now,t,true,a),externalTruckHook,externalTrailerHook);
            assert(float.IsFinite(radius)&&t.Corners().Concat(a.Corners()).All(p=>Vector3.Distance(p,t.Position)<radius),
                "Genuinely supplied exterior hooks and the allowed world-joint error remain enclosed under arbitrary coupled 3D rotations");
        }
        var extremeHook=new Vector3(50.1f,0,0);
        assert(float.IsNaN(RigReach.Radius(new(321,1,2,Now,truck,true,trailer with{Position=extremeHook}),extremeHook,Vector3.Zero)),
            "Removing the unnecessary inside-box restriction must retain the explicit 50m hook plausibility limit");
    }
    public static void PhysicalSceneHold(Action<bool,string> assert)
    {
        var hold=new SceneHoldBrake();var point=new Vector3(20,0,30);
        foreach(double time in new[]{0d,.3,.8,2,10,30}) {
            // Target information may change completely while this physical
            // point remains fixed; the API intentionally has no target input.
            assert(hold.Step("physical-stop",time,0,point,true)==.35f,"Long stationary scene holds do not invent creep from recomputed obstacle or scope targets");
        }
        assert(hold.Step("physical-stop",30.1,.4,point+Vector3.UnitZ*.04f,true)>=.35f,"Actual own motion starts physical creep tracking");
        assert(hold.Step("physical-stop",30.5,.4,point+Vector3.UnitZ*.20f,true)>=.65f,"Measured sustained physical creep escalates the floor");
        assert(hold.Step("physical-stop",31,.4,point+Vector3.UnitZ*.4f,true)==1,"Continued physical creep reaches full hold braking");
        assert(hold.Step("physical-stop",31.1,0,point+Vector3.UnitZ*.4f,false)==0,"Withdrawal of authority immediately ends a scene hold");
        assert(hold.Step("other-stop",32,0,point+Vector3.UnitX*100,true)==.35f,"A new physical stop does not inherit old drift or full brake state");
        hold.Reset();assert(hold.Step("other-stop",33,0,point,true)==.35f,"Manual cancellation resets the old physical origin");
        assert(hold.Step("other-stop",34,0,new(float.NaN,0,0),true)==0,"Invalid physical pose cannot renew a hold lease");

        var latched=new SceneStopHold();
        assert(latched.Step(0,.4,point,1,true)==.35f&&latched.Holding,
            "The actual reserve-adjusted 1m/.4mps counterexample establishes a physical hold");
        foreach(double t in new[]{.1,.5,2,10,30}) {
            assert(latched.Step(t,0,point,1,true)==.35f&&latched.Holding,
                "Removing the speed reserve at standstill cannot release the unresolved physical stop");
            assert(latched.Limit(.35f)<=-.6f,
                "The positive planned approach target cannot restart the stopped truck while the unresolved set persists");
        }
        assert(latched.Step(31,0,point,100,true)==.35f,
            "Changing an unresolved target's computed distance cannot impersonate a positive clear-scene result");
        assert(latched.Limit(float.NaN)==-.6f&&latched.Limit(-3)==-3,
            "The latched hold adds a missing negative target without weakening a stronger existing brake");
        latched.Reset();
        assert(!latched.Holding&&latched.Limit(.35f)==.35f&&latched.Step(32,0,point,100,true)==0,
            "An explicit all-checks-clear reset releases the previous physical stop and permits a distant approach");
        latched.Step(33,0,point,0,true);
        assert(latched.Step(33.1,0,point,0,false)==0&&!latched.Holding&&latched.Limit(.35f)==.35f,
            "Driver authority withdrawal clears both the physical brake and the negative target latch");
        var owners=new SceneStopHold();
        owners.Step(0,0,point,0,true,"near-plaza-A");
        assert(owners.Step(1,0,point,100,true,"distant-plaza-B")==0&&!owners.Holding&&owners.Limit(.35f)==.35f,
            "Proved resolution of A permits a normal approach to a distinct distant unresolved B");
        owners.Step(2,0,point,0,true,"near-plaza-C");
        owners.Step(2.1,.4,point+Vector3.UnitZ*.05f,0,true,"near-plaza-C");
        assert(owners.Step(3,.4,point+Vector3.UnitZ*.4f,0,true,"near-plaza-C")==1,
            "An actual sustained creep before ownership change establishes the stronger full physical floor");
        assert(owners.Step(3.1,0,point+Vector3.UnitZ*.4f,1,true,"near-body-D")==1&&owners.Holding,
            "A different still-near unresolved cause cannot reset the already needed physical brake");
    }
    public static void PartialSafety(Action<bool,string> assert)
    {
        var raw=Frame();U32(raw,28,58);U32(raw,104,3);U32(raw,80,1);U32(raw,84,1);Body(raw,0,flags:2);
        assert(SceneSnapshotProtocol.Decode(raw,Now,Pid)==null,"Normal decode never grants authority to an incomplete scene");
        var partial=SceneSnapshotProtocol.Decode(raw,Now,Pid,true);
        assert(partial?.Bodies.Count==1&&partial.Diagnostic==3&&partial.Synchronized(Vector3.Zero,2000000,2000000),"Opt-in safety decode retains validated present bodies with their original failure cause");
        assert(!partial!.Covers(55,Vector3.Zero,30,2000000,2000000),"A partial body list cannot claim absence coverage, even when bodyTotal equals its exported count");
        foreach(var header in new (int Offset,uint Value)[]{(28,59),(28,62),(28,50),(28,42),(104,0),(104,8),(24,322),(12,3)}) {
            var bad=(byte[])raw.Clone();U32(bad,header.Offset,header.Value);
            assert(SceneSnapshotProtocol.Decode(bad,Now,Pid,true)==null,"Incomplete safety observations preserve strict PID, pause, pose, clock, diagnostic and seqlock requirements");
        }
        assert(SceneSnapshotProtocol.Decode(raw,Now+201,Pid,true)==null,"Partial positive-body evidence expires with the same source deadline");
        var corrupt=(byte[])raw.Clone();corrupt[112]^=1;
        assert(SceneSnapshotProtocol.Decode(corrupt,Now,Pid,true)==null,"Safety-only mode does not waive the actual producer build identity");
        corrupt=(byte[])raw.Clone();F32(corrupt,160+44,float.NaN);
        assert(SceneSnapshotProtocol.Decode(corrupt,Now,Pid,true)==null,"An invalid observed body does not become positive evidence through partial mode");
        var timeline=new SceneTimeline();timeline.Accept(partial,Now);
        assert(!timeline.Accept(partial with{Diagnostic=4},Now+1),"Even incomplete same-sequence snapshots cannot mutate their producer diagnostics");
    }
}
